  kind:
    | "weakest_topic"
    | "strongest_topic"
    | "pace_slow"
    | "pace_fast"
    | "changes_hurt"
    | "changes_helped"
    | "flags_right"
    | "underweighted"
    | "trend_up"
    | "trend_down";
